import fixtureJson from '../../oracles/fixtures/statistics-spatial-regression.json';
import {decodeOracleFixture} from '../../oracles/oracle-fixture';

/**
 * Reference values from PySAL (spreg 1.9.1, libpysal 4.15.0; float64) for `GM_Error`, generated by
 * `test/oracles/statistics-spatial-regression.py` on the `frozen` scenes of
 * `test/oracles/fixtures/statistics-regression-scenes.json` (seeded spatial error scenes (`y = 1 + 2 x1 - x2 + (I - lambda W)^-1 eps`,
 * float32-rounded `y` and `X`; their original generator was not kept) fit with `spreg.GM_Error(y, X, w)`. The weights are passed to spreg as
 * `libpysal.weights.W` with the exact CSR values below (original transform), so both sides see
 * identical inputs.
 * - `lattice`: rook `10 x 10` lattice, row-standardized, generating lambda 0.6.
 * - `knn`: 80 random points, 4 nearest neighbors each, row-standardized, an asymmetric pattern,
 *   generating lambda 0.5.
 * `standardErrors`, `zStatistics` and `pValues` are spreg's `std_err` and `z_stat` for the betas
 * (intercept first); spreg gives no standard error for lambda.
 */
export type SpregErrorGMFixture = {
  offsets: number[];
  neighbors: number[];
  weights: number[];
  predictors: number[];
  response: number[];
  betas: number[];
  lambda: number;
  standardErrors: number[];
  zStatistics: number[];
  pValues: number[];
  sigma2: number;
  pseudoRSquared: number;
};

/**
 * GM_Error_Hom reference (spreg 1.9.1, libpysal 4.15.0; float64), generated by
 * `test/oracles/statistics-spatial-regression.py` on `statistics-regression-scenes.json`: `spreg.GM_Error_Hom(y, X, w, A1="hom_sc", max_iter=1)` and
 * `spreg.GM_Error(y, X, w)` with the weights passed untransformed (transform "O").
 * - `lattice`, `knn`: the scenes of `SPREG_ERROR_GM_REFERENCE`.
 * - `binary`: `createErrorScene(324, 9, 0.5, "lattice-binary")` (18 x 18 rook lattice, binary weights,
 *   `||W||_inf = 4`, so the GPU bound is 0.2475; spreg runs on [-0.99, 0.99] and the estimates are interior).
 * `hom.standardErrors` and `hom.z`/`hom.p` hold the betas then `lambda` last (`vm` diagonal of spreg).
 * `conditioning`: numpy float64 conditioning of the final filtered regression at the reported lambda (Belsley of the raw
 * filtered [1, X]; correlation condition number and largest predictor VIF of [filtered constant, filtered centered X]).
 * `steps`: `lambda1` of spreg step 1, `G` and `psi` (row-major 2 x 2) at the second step, `psi1` at
 * `lambda1` and `psi2` at the final `lambda`.
 */
export type SpregErrorGMConditioning = {
  conditionNumber: number;
  correlationConditionNumber: number;
  maximumVarianceInflationFactor: number;
};

export type SpregErrorGMHomFixture = {
  rowSumNorm: number;
  hom: {
    betas: number[];
    lambda: number;
    standardErrors: number[];
    z: number[];
    p: number[];
    sigma2: number;
    pseudoRSquared: number;
    conditioning: SpregErrorGMConditioning;
  };
  kelejianPrucha: {
    betas: number[];
    lambda: number;
    standardErrors: number[];
    z: number[];
    p: number[];
    sigma2: number;
    pseudoRSquared: number;
    conditioning: SpregErrorGMConditioning;
  };
  steps: {
    lambda1: number;
    momentMatrix: number[];
    momentVector: number[];
    psiAtLambda1: number[];
    psiAtLambda: number[];
  };
};

const fixture = decodeOracleFixture<{
  errorGM: Record<'lattice' | 'knn', SpregErrorGMFixture>;
  errorGMHom: Record<'lattice' | 'knn' | 'binary', SpregErrorGMHomFixture>;
}>(fixtureJson);

export const SPREG_ERROR_GM_REFERENCE: Record<'lattice' | 'knn', SpregErrorGMFixture> =
  fixture.errorGM;

export const SPREG_ERROR_GM_HOM_REFERENCE: Record<
  'lattice' | 'knn' | 'binary',
  SpregErrorGMHomFixture
> = fixture.errorGMHom;
